import { ChangeDetectionStrategy, Component } from '@angular/core';
import { CommonModule } from '@angular/common';

interface TeamMember {
  name: string;
  role: string;
  image: string;
  bio: string;
}

@Component({
  selector: 'team',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './team.component.html',
  styleUrls: ['./team.component.css'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class TeamComponent {
  members: TeamMember[] = [
    {
      name: 'გელა მაჭავარიანი',
      role: 'შეფ-მზარეული',
      image: 'https://images.unsplash.com/photo-1577219491135-ce391730fb2c?w=600',
      bio: '15 წლიანი გამოცდილება ქართულ და ევროპულ სამზარეულოში.',
    },
    {
      name: 'თამარ გვერდწითელი',
      role: 'მზარეული',
      image: 'https://images.unsplash.com/photo-1583394293214-28ded15ee548?w=600',
      bio: 'სპეციალიზაცია დესერტებსა და ტრადიციულ ტკბილეულში.',
    },
    {
      name: 'ნია ბარათელი',
      role: 'მიმტანი',
      image: 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=600',
      bio: 'ყოველთვის მზადაა, რომ თქვენი ვიზიტი დაუვიწყარი გახადოს.',
    },
    {
      name: 'ვაჟა ბრეგვაძე',
      role: 'მიმტანი',
      image: 'https://images.unsplash.com/photo-1607631568010-a87245c0daf8?w=600',
      bio: 'კითხულობს თქვენს სურვილებს ნახევარი სიტყვიდან.',
    },
  ];
}
